export const PAST_PERFORMANCE_HEADER = "name,starts,wins,seconds,thirds,avgFinish,goodRate,softRate,heavyRate,badRate";
export function parsePastPerformanceCsv(text: string) {
  const lines = text.replace(/^\uFEFF/, "").split(/\r?\n/).map((line) => line.trim()).filter(Boolean); if (lines.length < 2) throw new Error("過去成績CSVにはヘッダー行と1頭以上のデータが必要です。");
  const split = (line: string) => line.split(/,(?=(?:[^"]*"[^"]*")*[^"]*$)/).map((cell) => cell.trim().replace(/^"|"$/g, "").replace(/""/g, '"'));
  const headers = split(lines[0]).map((item) => item.toLowerCase()); const aliases: Record<string, string[]> = { name: ["name", "馬名", "horse"], starts: ["starts", "出走数", "出走回数"], wins: ["wins", "勝利数", "1着数"], seconds: ["seconds", "2着数"], thirds: ["thirds", "3着数"], avgFinish: ["avgfinish", "平均着順"], goodRate: ["goodrate", "良馬場率"], softRate: ["softrate", "稍重率"], heavyRate: ["heavyrate", "重馬場率"], badRate: ["badrate", "不良馬場率"] };
  const valueAt = (row: string[], key: string) => { const index = headers.findIndex((header) => aliases[key].includes(header)); return index >= 0 ? row[index] : ""; };
  return lines.slice(1).map((line, index) => { const row = split(line); const name = valueAt(row, "name"); if (!name) throw new Error(`${index + 2}行目: 馬名がありません。`); const starts = Math.max(0, numberValue(valueAt(row, "starts"), 0)); const wins = Math.min(starts, Math.max(0, numberValue(valueAt(row, "wins"), 0))); const seconds = Math.min(starts - wins, Math.max(0, numberValue(valueAt(row, "seconds"), 0))); const thirds = Math.min(starts - wins - seconds, Math.max(0, numberValue(valueAt(row, "thirds"), 0))); const rate = (key: "goodRate" | "softRate" | "heavyRate" | "badRate") => { const raw = valueAt(row, key); return raw === "" ? -1 : clamp(numberValue(raw, -1)); }; return { name, starts, wins, seconds, thirds, avgFinish: clamp(numberValue(valueAt(row, "avgFinish"), 6), 1, 18), rates: { 良: rate("goodRate"), 稍重: rate("softRate"), 重: rate("heavyRate"), 不良: rate("badRate") } }; });
}

function calculatePerformanceProfile(horse: Horse, record: ReturnType<typeof parsePastPerformanceCsv>[number]) {
  const top3Rate = record.starts ? (record.wins + record.seconds + record.thirds) / record.starts * 100 : 0; const winRate = record.starts ? record.wins / record.starts * 100 : 0; const reliability = clamp(record.starts / 24, .25, 1); const strength = clamp(46 + winRate * .9 + top3Rate * .34 + (7 - record.avgFinish) * 4); const stamina = clamp(49 + top3Rate * .38 + (7 - record.avgFinish) * 3.6); const form = clamp(44 + winRate * .7 + top3Rate * .38 + (7 - record.avgFinish) * 3); const blend = reliability * .65; const rate = (going: Going) => record.rates[going] >= 0 ? record.rates[going] : horse.goingRates[going]; return { ...horse, starts: record.starts, winsPast: record.wins, secondsPast: record.seconds, thirdsPast: record.thirds, avgFinish: record.avgFinish, speed: Math.round(horse.speed * (1 - blend) + strength * blend), stamina: Math.round(horse.stamina * (1 - blend) + stamina * blend), form: Math.round(horse.form * (1 - blend) + form * blend), goingRates: { 良: rate("良"), 稍重: rate("稍重"), 重: rate("重"), 不良: rate("不良") } };
}

function parseCsv(text: string) {
  const lines = text.replace(/^\uFEFF/, "").split(/\r?\n/).map((line) => line.trim()).filter(Boolean);
  if (!lines.length) throw new Error("CSVにデータがありません。");
  const parseLine = (line: string) => { const cells: string[] = []; let current = ""; let quoted = false; for (let i = 0; i < line.length; i++) { const char = line[i]; if (char === '"') { if (quoted && line[i + 1] === '"') { current += '"'; i++; } else quoted = !quoted; } else if (char === "," && !quoted) { cells.push(current.trim()); current = ""; } else current += char; } cells.push(current.trim()); return cells; };
  const headers = parseLine(lines[0]).map((x) => x.toLowerCase());
  const aliases: Record<string, string[]> = { no: ["no", "馬番", "number"], name: ["name", "馬名", "horse"], style: ["style", "脚質"], speed: ["speed", "末脚", "スピード"], stamina: ["stamina", "持久力", "スタミナ"], start: ["start", "先行力", "スタート"], form: ["form", "近況", "調子"], popularity: ["popularity", "人気"], starts: ["starts", "出走数", "出走回数"], winsPast: ["wins", "勝利数", "1着数"], secondsPast: ["seconds", "2着数"], thirdsPast: ["thirds", "3着数"], avgFinish: ["avgfinish", "平均着順"], goodRate: ["goodrate", "良馬場率"], softRate: ["softrate", "稍重率"], heavyRate: ["heavyrate", "重馬場率"], badRate: ["badrate", "不良馬場率"] };
  const indexOf = (key: string) => headers.findIndex((header) => aliases[key].includes(header));
  const valueAt = (row: string[], key: string) => { const index = indexOf(key); return index >= 0 ? row[index] : ""; };
  const rows = lines.slice(1).map((line, rowIndex) => { const row = parseLine(line); const name = valueAt(row, "name"); if (!name) throw new Error(`${rowIndex + 2}行目: name / 馬名 がありません。`); const starts = Math.max(0, numberValue(valueAt(row, "starts"), 0)); const winsPast = Math.max(0, numberValue(valueAt(row, "winsPast"), 0)); const secondsPast = Math.max(0, numberValue(valueAt(row, "secondsPast"), 0)); const thirdsPast = Math.max(0, numberValue(valueAt(row, "thirdsPast"), 0)); const baseRates = { 良: clamp(numberValue(valueAt(row, "goodRate"), defaultGoingRates.良)), 稍重: clamp(numberValue(valueAt(row, "softRate"), defaultGoingRates.稍重)), 重: clamp(numberValue(valueAt(row, "heavyRate"), defaultGoingRates.重)), 不良: clamp(numberValue(valueAt(row, "badRate"), defaultGoingRates.不良)) }; return { no: Math.max(1, numberValue(valueAt(row, "no"), rowIndex + 1)), name, color: colors[rowIndex % colors.length], style: parseStyle(valueAt(row, "style")), speed: clamp(numberValue(valueAt(row, "speed"), 70)), stamina: clamp(numberValue(valueAt(row, "stamina"), 70)), start: clamp(numberValue(valueAt(row, "start"), 70)), form: clamp(numberValue(valueAt(row, "form"), 70)), popularity: Math.max(0, numberValue(valueAt(row, "popularity"), 0)), starts, winsPast, secondsPast, thirdsPast, avgFinish: clamp(numberValue(valueAt(row, "avgFinish"), starts ? 1 + (starts - winsPast - secondsPast - thirdsPast) * .5 : 6), 1, 18), goingRates: baseRates } as Horse; });
  if (rows.length < 2) throw new Error("2頭以上の馬データが必要です。");
  return rows;
}
